document.addEventListener('DOMContentLoaded', () => {
  try { initCustomCursor(); } catch(e) { console.warn('Custom cursor init skipped:', e); }
  try { initThemeSwitcher(); } catch(e) { console.warn('Theme switcher init skipped:', e); }
  try { initParticleCanvas(); } catch(e) { console.warn('Particles init skipped:', e); }
  try { initStaticMascot(); } catch(e) { console.warn('Mascot init skipped:', e); }
  try { initMobileMenu(); } catch(e) { console.warn('Mobile menu init skipped:', e); }
  try { initScrollReveal(); } catch(e) { console.warn('Scroll reveal init skipped:', e); }
  try { initCardTilt(); } catch(e) { console.warn('Card tilt init skipped:', e); }
  try { initSmoothScroll(); } catch(e) { console.warn('Smooth scroll init skipped:', e); }
  try { fetchGitHubRepos('peruvianMiau'); } catch(e) { console.warn('GitHub fetch skipped:', e); }
});

const EXCLUDED_REPOS = [
  'catch-up-master',
  'RumiLink_AcceptanceTests',
  'SIRAD_BaseDeDatos'
];

const CAT_CURSOR_NORM = 'data:image/png;base64,';
const CAT_CURSOR_POINT = 'data:image/png;base64,';
const CAT_WORK_IMG = 'data:image/png;base64,';

/**
 * Cursors personalizados:
 * - Cursor Normal: Gato sentado
 * - Cursor Pointer (al pasar sobre links/botones): Gato señalando con la patita
 */
function initCustomCursor() {
  const cursorStyle = document.createElement('style');
  cursorStyle.textContent = `
    *, body {
      cursor: url("${CAT_CURSOR_NORM}") 4 4, auto !important;
    }
    a, button, input, .project-card, .theme-toggle-btn, .nav-cta, .static-corner-mascot, [role="button"] {
      cursor: url("${CAT_CURSOR_POINT}") 6 6, pointer !important;
    }
  `;
  document.head.appendChild(cursorStyle);
}

function initThemeSwitcher() {
  const topbar = document.querySelector('.topbar');
  const actions = topbar?.querySelector('.header-actions');
  if (!topbar || !actions) return;

  const themes = [
    { name: 'cyberpunk', label: 'Violeta' },
    { name: 'emerald', label: 'Esmeralda' },
    { name: 'ocean', label: 'Océano' },
    { name: 'sunset', label: 'Atardecer' }
  ];

  const themeBtn = document.createElement('button');
  themeBtn.className = 'theme-toggle-btn';
  themeBtn.type = 'button';
  themeBtn.setAttribute('aria-label', 'Cambiar paleta de colores');
  themeBtn.setAttribute('title', 'Cambiar color de la página');
  themeBtn.setAttribute('aria-live', 'polite');

  // Restore the user's last selected palette when possible.
  let currentThemeIndex = 0;
  try {
    const savedTheme = localStorage.getItem('portfolio-theme');
    const savedIndex = themes.findIndex(theme => theme.name === savedTheme);
    if (savedIndex >= 0) currentThemeIndex = savedIndex;
  } catch (_) {}

  const applyTheme = () => {
    const theme = themes[currentThemeIndex];
    document.body.setAttribute('data-theme', theme.name);
    themeBtn.innerHTML = `<span class="theme-swatch" aria-hidden="true"></span><span class="theme-label">${theme.label}</span><span class="theme-arrows" aria-hidden="true">↻</span>`;
    themeBtn.setAttribute('aria-label', `Tema actual: ${theme.label}. Pulsa para cambiar`);
    themeBtn.setAttribute('title', `Tema: ${theme.label} · Cambiar paleta`);
    try { localStorage.setItem('portfolio-theme', theme.name); } catch (_) {}
  };

  themeBtn.addEventListener('click', (event) => {
    currentThemeIndex = (currentThemeIndex + 1) % themes.length;
    applyTheme();
    if (typeof createClickBurst === 'function') {
      createClickBurst(event.clientX, event.clientY);
    }
  });

  // Keep the theme control beside GitHub, inside the actions group.
  actions.appendChild(themeBtn);
  applyTheme();
}

function initParticleCanvas() {
  const canvas = document.createElement('canvas');
  canvas.id = 'bg-particles';
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;opacity:0.6;';
  document.body.prepend(canvas);

  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  let width = (canvas.width = window.innerWidth);
  let height = (canvas.height = window.innerHeight);

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const particles = Array.from({ length: 45 }, () => ({
    x: Math.random() * width,
    y: Math.random() * height,
    size: Math.random() * 2.5 + 0.5,
    speedX: (Math.random() - 0.5) * 0.4,
    speedY: (Math.random() - 0.5) * 0.4,
    alpha: Math.random() * 0.5 + 0.2
  }));

  let mouseX = width / 2;
  let mouseY = height / 2;

  window.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
  });

  function animate() {
    ctx.clearRect(0, 0, width, height);

    particles.forEach(p => {
      p.x += p.speedX;
      p.y += p.speedY;

      if (p.x < 0) p.x = width;
      if (p.x > width) p.x = 0;
      if (p.y < 0) p.y = height;
      if (p.y > height) p.y = 0;

      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(167, 139, 250, ${p.alpha})`;
      ctx.shadowBlur = 8;
      ctx.shadowColor = '#6ee7f9';
      ctx.fill();

      const dx = mouseX - p.x;
      const dy = mouseY - p.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 110) {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(mouseX, mouseY);
        ctx.strokeStyle = `rgba(110, 231, 249, ${0.15 * (1 - dist / 110)})`;
        ctx.lineWidth = 0.6;
        ctx.stroke();
      }
    });

    requestAnimationFrame(animate);
  }

  animate();
}

function initStaticMascot() {
  const mascot = document.createElement('div');
  mascot.className = 'static-corner-mascot';
  mascot.title = '¡Hazme clic!';
  mascot.innerHTML = `
    <div class="speech-bubble">¡Trabajando duro! 💻</div>
    <div class="cat-avatar-wrapper">
      <img src="${CAT_WORK_IMG}" class="cat-img" alt="Gato trabajando en el escritorio" />
    </div>
  `;
  document.body.appendChild(mascot);

  const quotes = [
    '¡Miauu! 🐾',
    'Figma & Vue.js 💻',
    'Diana Li Gayoso 🇵🇪',
    'Promedio 17.44! 🎓',
    '¡Cuidado con los bugs! 🐛',
    'Scrum & Git 🚀'
  ];

  mascot.addEventListener('click', (e) => {
    const bubble = mascot.querySelector('.speech-bubble');
    if (bubble) {
      const randomQuote = quotes[Math.floor(Math.random() * quotes.length)];
      bubble.textContent = randomQuote;
      bubble.classList.add('show');
      setTimeout(() => bubble.classList.remove('show'), 2500);
    }

    mascot.classList.add('jump');
    if (typeof createClickBurst === 'function') {
      createClickBurst(e.clientX, e.clientY);
    }

    setTimeout(() => mascot.classList.remove('jump'), 600);
  });
}

function createClickBurst(x, y) {
  for (let i = 0; i < 8; i++) {
    const spark = document.createElement('div');
    spark.className = 'click-spark';
    document.body.appendChild(spark);

    const angle = (Math.PI * 2 * i) / 8;
    const distance = 30 + Math.random() * 20;
    const destX = x + Math.cos(angle) * distance;
    const destY = y + Math.sin(angle) * distance;

    spark.style.left = `${x}px`;
    spark.style.top = `${y}px`;

    spark.animate([
      { transform: 'translate(0, 0) scale(1)', opacity: 1 },
      { transform: `translate(${destX - x}px, ${destY - y}px) scale(0)`, opacity: 0 }
    ], {
      duration: 500,
      easing: 'cubic-bezier(0, .9, .57, 1)'
    }).onfinish = () => spark.remove();
  }
}

function initMobileMenu() {
  const toggleBtn = document.querySelector('.menu-toggle');
  const nav = document.querySelector('nav');
  if (!toggleBtn || !nav) return;

  toggleBtn.addEventListener('click', () => {
    nav.classList.toggle('open');
    toggleBtn.setAttribute('aria-expanded', nav.classList.contains('open'));
  });

  nav.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      nav.classList.remove('open');
    });
  });
}

function initScrollReveal() {
  const reveals = document.querySelectorAll('.reveal');
  if (!('IntersectionObserver' in window)) {
    reveals.forEach(el => el.classList.add('visible'));
    return;
  }

  const observerOptions = {
    threshold: 0.15,
    rootMargin: '0px 0px -40px 0px'
  };

  const observer = new IntersectionObserver((entries, obs) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        obs.unobserve(entry.target);
      }
    });
  }, observerOptions);

  reveals.forEach(el => observer.observe(el));
}

function initCardTilt() {
  const cards = document.querySelectorAll('.code-card, .project-card, .stat, .contact-panel');

  cards.forEach(card => {
    card.addEventListener('mousemove', (e) => {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      const rotateX = ((y - centerY) / centerY) * -7;
      const rotateY = ((x - centerX) / centerX) * 7;

      card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-5px)`;
      card.style.transition = 'transform 0.1s ease-out';
    });

    card.addEventListener('mouseleave', () => {
      card.style.transform = '';
      card.style.transition = 'transform 0.5s ease-in-out, border-color 0.25s';
    });
  });
}

function initSmoothScroll() {
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;

      const targetElement = document.querySelector(targetId);
      if (targetElement) {
        e.preventDefault();
        targetElement.scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
      }
    });
  });
}

async function fetchGitHubRepos(username) {
  const apiNote = document.getElementById('api-note');
  const repoCountEl = document.getElementById('repo-count');
  const projectGrid = document.getElementById('projects');

  try {
    const response = await fetch(`https://api.github.com/users/${username}/repos?sort=updated&per_page=30`);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    const allRepos = await response.json();
    const filteredRepos = allRepos.filter(repo => !EXCLUDED_REPOS.includes(repo.name));

    if (repoCountEl) {
      repoCountEl.textContent = String(filteredRepos.length).padStart(2, '0');
    }

    if (filteredRepos && filteredRepos.length > 0 && projectGrid) {
      const staticHighlight = getVioraCardHtml();
      const reposToDisplay = filteredRepos.slice(0, 5);
      renderProjects(reposToDisplay, projectGrid, staticHighlight);

      if (apiNote) {
        apiNote.textContent = '✓ Repositorios sincronizados en tiempo real desde GitHub';
        apiNote.style.color = 'var(--cyan)';
      }
    }
  } catch (error) {
    console.warn('GitHub API fetch failed:', error);
    if (apiNote) {
      apiNote.textContent = 'Mostrando proyectos principales del perfil.';
    }
  }
}

function getVioraCardHtml() {
  return `
    <a class="project-card reveal visible highlight-card" href="https://github.com/upc-pre-lasi0730-2610-10215-arcadiadevs" target="_blank" rel="noreferrer">
      <div class="project-top">
        <span class="project-icon">🌱</span>
        <span class="external">↗</span>
      </div>
      <h3>Viora — Agtech Platform</h3>
      <p>Plataforma web para gestión y diagnóstico agrícola técnico. Diseñé dashboards en Figma y desarrollé la interfaz en Vue.js.</p>
      <div class="project-tags">
        <span>Vue.js</span>
        <span>Figma</span>
        <span>Scrum</span>
      </div>
    </a>
  `;
}

function renderProjects(repos, container, extraHtml = '') {
  if (!container) return;

  const repoIcons = ['⌘', '▤', '⌁', '◈', '✧', '✦', '⚛', '⚡'];

  const dynamicHtml = repos.map((repo, idx) => {
    const icon = repoIcons[idx % repoIcons.length];
    const description = repo.description || 'Proyecto disponible en el perfil de GitHub para explorar el código fuente.';
    const language = repo.language || 'Web';
    const stars = repo.stargazers_count > 0 ? `★ ${repo.stargazers_count}` : 'GitHub';

    return `
      <a class="project-card reveal visible" href="${repo.html_url}" target="_blank" rel="noreferrer">
        <div class="project-top">
          <span class="project-icon">${icon}</span>
          <span class="external">↗</span>
        </div>
        <h3>${escapeHtml(repo.name)}</h3>
        <p>${escapeHtml(description)}</p>
        <div class="project-tags">
          <span>${escapeHtml(language)}</span>
          <span>${stars}</span>
        </div>
      </a>
    `;
  }).join('');

  container.innerHTML = extraHtml + dynamicHtml;
  initCardTilt();
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

